const CATS = ["Entrega demorada", "Material dañado", "Faltante en la entrega", "Error de facturación", "Atención en sucursal", "Otros"];
const URG = ['baja', 'media', 'alta'];
let categoria = null, urgencia = null, motivo = null;
try {
  const resp = JSON.parse($input.first().json.response || '{}');
  if (CATS.includes(resp.categoria)) categoria = resp.categoria; else motivo = 'Categoría no reconocida (la IA respondió: ' + (resp.categoria || 'nada') + ')';
  urgencia = URG.includes(resp.urgencia) ? resp.urgencia : 'media';
} catch (e) { motivo = 'Respuesta de la IA inválida'; }
return [{ json: { categoria, urgencia, motivo_ia: motivo } }];

const r = $('CA85a_Preparar').first().json;
const c = $('CA85a_Buscar_cliente').first().json;
const m = $('CA85a_Enmascarar').first().json;
const ia = $('CA85a_Validar_IA').first().json;
const cola = [];
if (!ia.categoria) cola.push({ origen: 'reclamos', motivo: ia.motivo_ia, prioridad: 'media' });
return [{ json: { reclamo_json: JSON.stringify({ reclamo_id: r.reclamo_id, cliente_id: c.cliente_id || null, sucursal: r.sucursal, canal: r.canal,
  fecha_hora_ingreso: r.fecha_hora_ingreso, texto_enmascarado: m.texto_enmascarado, categoria: ia.categoria, urgencia: ia.urgencia,
  es_pedido_datos_personales: r.pedido_datos_personales }), cola_json: JSON.stringify(cola) } }];
